Ниже на четырёх языках программирования записан алгоритм. Получив на вход число
x
, этот алгоритм печатает два числа:
S
и
P
. Укажите наибольшее число
x
, при вводе которого алгоритм печатает сначала 7, а потом 3.
С++
Python
#include <iostream>
using namespace std;
int main()
{
int x, P, S, N;
cin >> x;
P = 1;
S = 0;
N = 0;
while (x > 0) {
N = N + 1;
S = S + (x % 4)
P = P * (x % 4)
x = x / 4;
}
S = S + N;
P = P + N;
cout << S << endl << P << endl;
return 0;
}
